/* An environment whose entries are cells that its variables forward to. */
enum { ENV_FORWARD = 6 };
/* Instance layouts beyond the builtin value types. */
enum { LAYOUT_EXCEPTION = SPY_LAST_TYPE + 1, LAYOUT_TYPE, LAYOUT_MODULE };
