        if (magnitude_bit(&exponent, bit)) {
            SPYValue *product = integer_multiply(c, result, power);
            SPYValue *next = product ? big_integer_binary(c, '%', product, m) : NULL;
            spy_release(product); spy_release(result); result = next;
        }
