    kept = name_local(own, "__annotations__");
    if (v->type == SPY_CLASS && !kept) kept = name_local(own, "__annotations_cache__");
    if (kept && (v->type != SPY_FUNCTION || kept->type != SPY_NONE)) return NULL;
    annotate = name_local(own, "__annotate__");
