    if (c->error_type[0] || !(copy = value_new(c, SPY_CODE))) goto done;
    copy->as.unit.owner = spy_retain(owner);
    copy->as.unit.definition = def;
    copy->as.unit.replaced = replaced; replaced = NULL;
