    /* Its statements were compiled as they were parsed (body_begin,
     * lambda_kept); one without them is unevaluated, and none runs. */
    Program *p = n->scope->flat;
    if (!p) return 0;
    if (generator) { n->scope->code = p; n->scope->flat = NULL; }
