static size_t utf8_valid(const unsigned char *, size_t, const char **, size_t *);
static void attach_syntax_error(SPYContext *c, const char *filename, const char *source,
                                const char *position, const char *finish, int trim_line) {
    int end_zero = trim_line & 2, textless = trim_line & 4, end_minus = trim_line & 8, zero_based = trim_line & 16, unterminated = trim_line & 32,
        line_begun = trim_line & 64;
    trim_line &= 1;
    char type[sizeof(c->error_type)], message[sizeof(c->error_message)];
    memcpy(type, c->error_type, sizeof(type)); memcpy(message, c->error_message, sizeof(message));
    size_t line = c->line;
    const char *start = source;
    for (size_t at = 1; at < line && *start; at++) {
        const char *next = strchr(start, '\n');
        start = next ? next + 1 : start + strlen(start);
    }
    const char *end = strchr(start, '\n');
    end = end ? end + 1 : start + strlen(start);
    if (trim_line && end > start && end[-1] == '\n') end--;
    if (line_begun) position = finish = start;
    size_t offset = 1, end_offset = 1, end_line = line;
    if (position) {
        /* Columns count characters; without the line's text, the compiler's count UTF-8 bytes. */
        for (const char *ch = start; ch < position; ch++) if (textless || ((unsigned char)*ch & 192) != 128) offset++;
        end_offset = offset;
        /* A range may run onto later lines, through an explicit line join. */
        const char *end_start = NULL;
        for (const char *ch = position; ch < finish; ch++)
            if (*ch == '\n' && ch + 1 < finish) { end_line++; end_offset = 1; end_start = ch + 1; }
            else if (textless || ((unsigned char)*ch & 192) != 128) end_offset++;
        /* CPython converts an end on a later line against the first line's
         * text: its byte column, at most that line's length, in characters. */
        if (end_start && !textless) {
            size_t column = (size_t)(finish - end_start), length = (size_t)(end - start) - (end > start && end[-1] == '\n');
            end_offset = 1;
            for (const char *ch = start; ch < start + (column < length ? column : length); ch++)
                if (((unsigned char)*ch & 192) != 128) end_offset++;
        }
        if (end_zero) end_offset = 0;
        if (zero_based) offset--;
    }
    char *whole = c->error_text;
    c->error_text = NULL;
    spy_clear_error(c);
    SPYValue *details = value_new(c, SPY_TUPLE);
    SPYValue *msg = whole ? spy_string(c, whole, strlen(whole)) : spy_string(c, message, strlen(message));
    mem_free(whole);
    /* The line's text, decoded with replacement characters. */
    Buffer text = {.ctx = c};
    for (const char *ch = start; ch < end;) {
        const char *reason;
        size_t bad = 1, width = utf8_valid((const unsigned char *)ch, (size_t)(end - ch), &reason, &bad);
        if (width) append(&text, ch, width);
        else append_codepoint(&text, 0xfffd);
        ch += width ? width : bad;
    }
    if (!trim_line && !unterminated && (end == start || end[-1] != '\n')) puts_buffer(&text, "\n");
    SPYValue *fields[] = {
        spy_string(c, filename, strlen(filename)), spy_int(c, (int64_t)line),
        position ? spy_int(c, (int64_t)offset) : spy_none(c),
        textless ? spy_none(c) : spy_string(c, text.data ? text.data : "", text.len),
        position ? spy_int(c, (int64_t)end_line) : spy_none(c),
        position ? spy_int(c, end_minus ? -1 : (int64_t)end_offset) : spy_none(c)
    };
    mem_free(text.data);
    for (size_t i = 0; i < sizeof(fields) / sizeof(*fields); i++) {
        if (!c->error_type[0] && details && fields[i]) sequence_append(c, details, fields[i]);
        spy_release(fields[i]);
    }
    SPYValue *args[] = {msg, details};
    SPYValue *error = c->error_type[0] ? NULL : call(c, name_local(c->classes, type), 2, args);
    spy_release(msg); spy_release(details);
    if (error) {
        chain_exception(c, error);
        c->exception = error;
        memcpy(c->error_type, type, sizeof(type)); memcpy(c->error_message, message, sizeof(message));
        put_text(c->filename, sizeof(c->filename), filename); c->filename_from = c->quiet_unit = NULL;
        c->line = line;
    }
}
/* The parameters of a replace()d code object whose signature changed, or NULL. */
static Parameter *replaced_signature(SPYValue *code) {
    return code->as.unit.owner && code->as.unit.definition ? code->as.unit.signature : NULL;
}
static Parameter *function_parameters(SPYValue *fn) {
    return fn->as.function.signature ? fn->as.function.signature : fn->as.function.def->signature;
}
/* A parameter's value in env, or NULL while it is unbound. */
