    size_t i = 0;
    while (i < argc && UINT64_C(1) << argv[i]->type & (UINT64_C(1) << SPY_INT | UINT64_C(1) << SPY_FLOAT | UINT64_C(1) << SPY_STRING |
                                                     UINT64_C(1) << SPY_BYTES | UINT64_C(1) << SPY_BOOL | UINT64_C(1) << SPY_NONE)) i++;
