    if (c->error_type[0]) { spy_release(items); return NULL; }
    if (star == SIZE_MAX) return items;
    SPYValue *rest = spy_list(c), *result = spy_list(c);
    if (!rest || !result) { spy_release(rest); spy_release(result); spy_release(items); return NULL; }
