        if (!key) { spy_error(c, "TypeError", "keywords must be strings"); goto failed; }
        if (!strcmp(key->as.string.data, "metaclass")) meta = entry->value;
        else if (map_append(c, s->keywords, entry->key, entry->value, entry->hash)) goto failed;
