    int id = (int)state->as.seq.items[0]->as.integer_data.small;
    SPYValue *args[2] = {NULL, NULL}, *value;
    for (size_t i = 0; i < argc; i++) args[i] = spy_retain(state->as.seq.items[1 + i]);
