    if (id == B_OBJECT_REDUCE_EX && spy_as_int(c, argv[1], &protocol)) return k(c, m, ctx, NULL);
    /* Protocols 0 and 1 reconstruct from the first class of the
     * Standard in the MRO (CPython: the first non-heap type). */
