        spy_release(callbacks->as.seq.items[0]); callbacks->as.seq.items[0] = cls;
        spy_release(items[BUILD_CALLBACKS]); items[BUILD_CALLBACKS] = callbacks;
        spy_release(items[BUILD_STAGE]);
