        return spy_retain(v);
    case P_COPY: return spy_retain(top[-(ptrdiff_t)operand]);
    case P_BIND:
        spy_release(top[-(ptrdiff_t)operand]);
        top[-(ptrdiff_t)operand] = machine_pop(m);
        return c->stepped;
