            if (name_set(c, f->env, ins->constant->as.seq.items[i]->as.string.data, top[(ptrdiff_t)i + 1 - (ptrdiff_t)operand])) return NULL;
        for (size_t i = 0; i < operand; i++) spy_release(machine_pop(m));
