        for (size_t i = 0; i < operand / 2; i++) { SPYValue *swap = top[-(ptrdiff_t)i]; top[-(ptrdiff_t)i] = top[(ptrdiff_t)i + 1 - (ptrdiff_t)operand]; top[(ptrdiff_t)i + 1 - (ptrdiff_t)operand] = swap; }
