    if ((key->type != SPY_TUPLE && key->type != SPY_LIST) || !depth || !key->listed) return 0;
    for (size_t i = 0; i < key->as.seq.len; i++) if (sort_reaches(key->as.seq.items[i], depth - 1)) return 1;
    return 0;
