    if (!result) return -1;
    if (s->phase == 1) { spy_release(result); s->phase = 2; return 0; }
    if (s->phase == 2) { s->item = result; s->phase = 3; return 0; }
    spy_release(s->item); s->item = NULL; s->phase = 0;
    return keys_listing(c, top, result);
