    if (!strcmp(method, "bytes") || !strcmp(method, "bytearray")) return buffer_copied(c, m, v, method[4] == 'a', result);
    if (!strcmp(method, "__int__") || !strcmp(method, "__float__")) return number_result(c, v, method[2] == 'f', spy_retain(result));
