static int convert_call(SPYContext *, Machine *, SPYValue *, SPYValue *, SPYValue *, SPYValue *, SPYValue **, SPYValue **);
static int next_call_of(SPYContext *, Machine *, SPYValue *, SPYValue **, SPYValue **);
