        if (result || !error_is(c, "KeyError")) return result;
        spy_clear_error(c);
        if (op == FL_SETDEFAULT && !(result = frame_locals_method(c, 3, (SPYValue *[]){proxy, args[0], value}, NULL, (void *)FL_SETITEM))) return NULL;
