        SPYValue *list = frame_contents(c, frame, op == FL_VALUES ? FRAME_VALUES : op == FL_ITEMS ? FRAME_ITEMS : FRAME_KEYS);
        if (!list || op == FL_KEYS || op == FL_VALUES || op == FL_ITEMS) return list;
