        if (isinf(x)) return x > 0 ? spy_string(c, "inf", 3) : spy_string(c, "-inf", 4);
        if (x == 0) return signbit(x) ? spy_string(c, "-0x0.0p+0", 9) : spy_string(c, "0x0.0p+0", 8);
