static SPYValue *buffer_kept(SPYContext *, SPYValue *, SPYValue **, SPYValue *);
static SPYValue *buffer_bytes(SPYContext *c, SPYValue *v, SPYValue **owned) { return buffer_kept(c, v, owned, NULL); }
