        if (argc != 2 && argc != 4) return spy_error(c, "TypeError", "type.__init__() takes 1 or 3 arguments");
        if (argc == 2 && keywords && keywords->as.map.len) return spy_error(c, "TypeError", "type.__init__() takes no keyword arguments");
