static SPYValue *resume(SPYContext *);
void spy_context_free(SPYContext *c) {
    if (!c) return;
    if (c->paused_at) {
        /* Stopped, the paused call unwinds without running a step. */
        enter(c);
        halt(c, SPY_STOP_INTERRUPT);
        spy_release(resume(c));
        leave(c, NULL);
    }
    /* Context destruction invalidates every value. Free storage directly so
     * shutdown cannot recurse through an arbitrarily deep object graph. */
    c->weak_len = 0;
    /* Kept environments' keys are values freed below. */
    for (SPYValue *v = c->values; v; v = v->next)
        if (v->type == V_UNIT) {
            for (Node *n = v->as.unit.nodes; n; n = n->allocated) if (node_root(v, n->scope)) drop_kept_tree(c, n->scope);
            drop_kept_tree(c, v->as.unit.scope);
        }
    c->frames_cap = 0;
    while (c->values) free_value(c->values);
    while (c->sealed) free_value(c->sealed);
    mem_free(c->weak); mem_free(c->weak_calls); mem_free(c->cells); mem_free(c->frames); mem_free(c->repr_stack);
    for (size_t i = 0; i < c->host_modules_len; i++) mem_free(c->host_modules[i].name);
    mem_free(c->host_modules);
    for (size_t i = 0; i < c->mounts_len; i++) { mem_free(c->mounts[i].host); mem_free(c->mounts[i].path); }
    mem_free(c->mounts);
#if SPY_FILES
    for (size_t i = 0; i < c->files_len; i++) close(c->files[i]);
#endif
    mem_free(c->files); mem_free(c->error_display);
    for (size_t i = 0; i < sizeof(c->tuple_cache) / sizeof(*c->tuple_cache); i++)
        if (c->tuple_cache[i]) { cache_take(c->tuple_cache[i], class_bytes(tuple_class(i))); value_give(c, c->tuple_cache[i], tuple_class(i)); }
    /* The unlisted values still live go with their pools. */
    while (c->every_pool) {
        Pool *pool = c->every_pool;
        c->every_pool = pool->after;
        cache_take(pool, POOL); pool_free(pool);
    }
    while (c->spare_entries_len) mem_free(c->spare_entries[--c->spare_entries_len]);
    if (c->spare_machine) { mem_free(c->spare_machine->blocks); mem_free(c->spare_machine->stack); mem_free(c->spare_machine); }
    calls_free(c, 0);
    free_program(c->compare_code);
    mem_free(c->calls);
    for (int k = 0; k < 16; k++)
        for (MemHead *b = c->spare_blocks[k], *next; b; b = next) { cache_take(b, sizeof(*b) + (k + 1) * 16); next = b->next; free(b); }
    free(c);
}
/* Writes to the host output, or with error the error stream, within the
 * output limit. */
static int output_write(SPYContext *c, int error, const char *text, size_t n) {
    int own = error && c->error_write;
    SPYWrite write = own ? c->error_write : c->write;
    if (!write) { spy_error(c, "OSError", "no output callback installed"); return -1; }
    /* A host function may have lowered the limit below what was written. */
    if (c->output_limit && (c->output_used > c->output_limit || n > c->output_limit - c->output_used))
        return halt(c, SPY_STOP_OUTPUT);
    c->output_used += n;
    if (!write(c, own ? c->error_data : c->write_data, text, n)) return 0;
    spy_error(c, "OSError", "output failed");
    return -1;
}
void spy_set_output(SPYContext *c, SPYWrite write, SPYFlush flush, void *data) { c->write = write; c->flush = flush; c->write_data = data; }
void spy_set_error_output(SPYContext *c, SPYWrite write, SPYFlush flush, void *data) {
    c->error_write = write; c->error_flush = flush; c->error_data = data;
}
void spy_set_module_loader(SPYContext *c, SPYModuleLoader loader, void *data) { c->loader = loader; c->loader_data = data; }
void spy_set_input(SPYContext *c, SPYReadLine read_line, void *data) { c->read_line = read_line; c->read_data = data; }
/* argc strings as a list of str, decoded as UTF-8 with surrogateescape. */
static SPYValue *argv_list(SPYContext *c, size_t argc, const char *const *argv) {
    SPYValue *errors = spy_string(c, "surrogateescape", 15), *list = errors ? spy_list(c) : NULL;
    for (size_t i = 0; list && i < argc; i++) {
        SPYValue *item = bytes_decode(c, argv[i], strlen(argv[i]), NULL, errors);
        if (!item || spy_list_append(c, list, item)) { spy_release(list); list = NULL; }
        spy_release(item);
    }
    spy_release(errors);
    return list;
}
int spy_set_argv(SPYContext *c, size_t argc, const char *const *argv, size_t orig_argc, const char *const *orig_argv) {
    SPYValue *list = argv_list(c, argc, argv), *orig = list ? argv_list(c, orig_argc, orig_argv) : NULL;
    if (!orig) { spy_release(list); return -1; }
    spy_release(c->argv); spy_release(c->orig_argv);
    c->argv = list; c->orig_argv = orig;
    return 0;
}
void spy_set_policy(SPYContext *c, SPYPolicy policy, void *data) { c->policy = policy; c->policy_data = data; }
int spy_policy_check(SPYContext *c, const char *event, SPYValue *args) {
    if (!c->policy || (!c->policy(c, c->policy_data, event, args) && !c->error_type[0])) return 0;
    errorf(c, "PermissionError", "%s is not allowed by the host policy", event);
    return -1;
}
void spy_set_interrupt(SPYContext *c, SPYInterrupt interrupt, void *data) {
    c->interrupt = interrupt; c->interrupt_data = data; c->quiet_unit = NULL;
    schedule_poll(c); watch(c);
}
size_t spy_memory_used(const SPYContext *c) { return c->memory; }
int spy_stopped(const SPYContext *c) { return c->stopped; }
int spy_set_limit(SPYContext *c, int limit, size_t value) {
    switch (limit) {
    case SPY_LIMIT_STEPS: c->step_limit = value; watch(c); return 0;
    case SPY_LIMIT_MEMORY: c->memory_limit = value; watch(c); return 0;
    case SPY_LIMIT_OUTPUT: c->output_limit = value; watch(c); return 0;
    case SPY_LIMIT_RECURSION: if (value <= c->py_depth) break; c->recursion_limit = value; return 0;
    case SPY_LIMIT_INT_DIGITS: if (value && value < 640) break; c->int_max_str_digits = value; return 0;
    case SPY_LIMIT_STACK: if (!value) break; c->stack_size = value; return 0;
    case SPY_LIMIT_COLLECTION: c->collection_limit = value; schedule_collection(c); return 0;
    case SPY_LIMIT_PAUSE: if (value > 1) break; c->pausing = (int)value; return 0;
    default: spy_error(c, "ValueError", "unknown limit"); return -1;
    }
    spy_error(c, "ValueError", "limit value out of range");
    return -1;
}
size_t spy_get_limit(const SPYContext *c, int limit) {
    switch (limit) {
    case SPY_LIMIT_STEPS: return c->step_limit;
    case SPY_LIMIT_MEMORY: return c->memory_limit;
    case SPY_LIMIT_OUTPUT: return c->output_limit;
    case SPY_LIMIT_RECURSION: return c->recursion_limit;
    case SPY_LIMIT_INT_DIGITS: return c->int_max_str_digits;
    case SPY_LIMIT_STACK: return c->stack_size;
    case SPY_LIMIT_COLLECTION: return c->collection_limit;
    case SPY_LIMIT_PAUSE: return (size_t)c->pausing;
    default: return 0;
    }
}
size_t spy_steps_used(const SPYContext *c) {
    return (c->step_limit ? c->step_limit : SIZE_MAX) - (c->stopped ? c->stopped_fuel : c->fuel);
}
void spy_set_optimize(SPYContext *c, int level) { c->optimize = level < 0 ? 0 : level > 2 ? 2 : level; }
static SPYValue *source_end(SPYContext *, SPYValue *, Result);
static SPYValue *eval_source(SPYContext *c, const char *source, const char *filename, int interactive) {
    spy_clear_error(c);
    /* An outermost call pauses while no other is paused. */
    int pausable = c->pause_entry = !interactive && c->entries == 1 && c->pausing && !c->pause_root;
    c->interactive_input = interactive;
    SPYValue *unit = parse(c, source, strlen(source), filename ? filename : "<string>");
    c->interactive_input = 0;
    Frame frame = {c->globals, unit, interactive};
    Result result = unit ? execute_module(c, &frame) : (Result){FLOW_ERROR, NULL};
    c->pause_entry = 0;
    if (result.flow == FLOW_PAUSE) { c->paused_unit = unit; return NULL; }
    /* A pause due in its parsing or compiling ends with the call. */
    if (pausable) c->pause_due = 0;
    return unit ? source_end(c, unit, result) : NULL;
}
/* The value of evaluating unit, which ended with result. */
static SPYValue *source_end(SPYContext *c, SPYValue *unit, Result result) {
    spy_release(unit);
    /* Deaths in the last statement have no later statement boundary. */
    if (result.flow != FLOW_ERROR && (c->weak_calls_len || c->finalize_calls_len)) weak_callbacks(c);
    if (result.flow == FLOW_ERROR) { spy_release(result.value); return NULL; }
    return result.value ? result.value : spy_none(c);
}
/* The host calls in. The outermost call clears a stop and gets the whole
 * step budget; a host function calling back shares its caller's. */
static void enter(SPYContext *c) {
    if (c->entries++) return;
    c->fuel = c->step_limit ? c->step_limit : SIZE_MAX;
    schedule_poll(c);
    c->stopped = 0; c->output_used = 0;
}
static SPYValue *leave(SPYContext *c, SPYValue *result) { error_settle(c); c->entries--; return result; }
int spy_paused(const SPYContext *c) { return c->paused_at ? c->pause_due : 0; }
/* Run the paused call on from its step: to its end, or to its next pause. */
static SPYValue *resume(SPYContext *c) {
    Machine *at = c->paused_at;
    c->paused_at = NULL;
    c->eval_env = c->paused_env;
    Result r = run_machine(c, at, NULL, NULL, 0, NULL);
    if (r.flow == FLOW_PAUSE) { c->paused_env = c->eval_env; c->eval_env = c->paused_outer; return NULL; }
    SPYValue *unit = c->paused_unit;
    c->paused_unit = NULL;
    return source_end(c, unit, module_left(c, module_end(c, c->pause_root, c->paused_outer, r)));
}
SPYValue *spy_resume(SPYContext *c) {
    if (!c->paused_at) { spy_error(c, "RuntimeError", "no call is paused"); return NULL; }
    enter(c);
    spy_clear_error(c);
    c->pause_due = 0;
    return leave(c, resume(c));
}
SPYValue *spy_eval(SPYContext *c, const char *source, const char *filename) {
    enter(c); return leave(c, eval_source(c, source, filename, 0));
}
SPYValue *spy_eval_interactive(SPYContext *c, const char *source, const char *filename) {
    enter(c); return leave(c, eval_source(c, source, filename, 1));
}
/* The final value dies here, after the last statement boundary. */
int spy_exec(SPYContext *c, const char *source, const char *filename) {
    enter(c);
    SPYValue *v = eval_source(c, source, filename, 0);
    int status = v ? 0 : -1;
    spy_release(v);
    if (!status && (c->weak_calls_len || c->finalize_calls_len)) weak_callbacks(c);
    leave(c, NULL);
    return status;
}
/* Embedding API over the evaluator's own operations. */
SPYValue *spy_native(SPYContext *c, const char *name, SPYNativeKeywords call, void *data, void (*release)(void *)) {
    SPYValue *v = value_new(c, SPY_NATIVE);
    if (!v) { if (release) release(data); return NULL; }
    v->as.native.kwcall = call; v->as.native.data = data; v->as.native.release = release; v->as.native.host = 1;
    v->as.native.name = spy_string(c, name, strlen(name));
    if (!v->as.native.name) { spy_release(v); return NULL; }
    return v;
}
SPYValue *spy_call_keywords(SPYContext *c, SPYValue *fn, size_t argc, SPYValue *const *argv, SPYValue *keywords) {
    if (keywords && (!same_context(c, keywords) || !is_dict(keywords))) return spy_error(c, "TypeError", "keywords must be a dict");
    if (!same_contexts(c, argc, argv)) return NULL;
    enter(c); return leave(c, call_keywords(c, fn, argc, argv, keywords && keywords->as.map.len ? keywords : NULL));
}
SPYValue *spy_tuple(SPYContext *c, size_t n, SPYValue *const *items) {
    SPYValue *tuple = value_alloc(c, SPY_TUPLE, n);
    for (size_t i = 0; tuple && i < n; i++)
        if (!same_context(c, items[i]) || sequence_append(c, tuple, items[i])) { spy_release(tuple); return NULL; }
    return tuple;
}
SPYValue *spy_dict(SPYContext *c) { return value_new(c, SPY_DICT); }
SPYValue *spy_get_item(SPYContext *c, SPYValue *v, SPYValue *key) {
    return same_context(c, v) && same_context(c, key) ? settled(c, get_index(c, v, key)) : NULL;
}
int spy_set_item(SPYContext *c, SPYValue *v, SPYValue *key, SPYValue *item) {
    return same_context(c, v) && same_context(c, key) && same_context(c, item) ? settled_status(c, set_index(c, v, key, item)) : -1;
}
SPYValue *spy_get_attr(SPYContext *c, SPYValue *v, const char *name) {
    return same_context(c, v) ? settled(c, attribute(c, v, name)) : NULL;
}
int spy_set_attr(SPYContext *c, SPYValue *v, const char *name, SPYValue *item) {
    return same_context(c, v) && same_context(c, item) ? settled_status(c, set_attribute(c, v, name, item)) : -1;
}
SPYValue *spy_iter(SPYContext *c, SPYValue *v) { return same_context(c, v) ? settled(c, get_iterator(c, v)) : NULL; }
SPYValue *spy_next(SPYContext *c, SPYValue *iterator) { return same_context(c, iterator) ? settled(c, iterator_next(c, iterator)) : NULL; }
SPYValue *spy_str(SPYContext *c, SPYValue *v) { return same_context(c, v) ? settled(c, stringify(c, v, 0)) : NULL; }
SPYValue *spy_error_value(SPYContext *c) {
    if (!c->error_type[0]) return NULL;
    ErrorState state = take_error(c);
    SPYValue *value = spy_retain(state.value);
    restore_error(c, &state);
    return value;
}
SPYValue *spy_raise(SPYContext *c, SPYValue *exception) {
    return same_context(c, exception) ? settled(c, raise_value(c, exception)) : NULL;
}
/* Host files. open() is the intrinsic io layer over these _spy primitives,
 * which reach only mounted directories and descriptors this context opened. */
/* input([prompt]): flush, write str(prompt), and read a line from the host's
 * reader without its line ending. No reader, or its end, is EOFError. */
static SPYValue *input_builtin(SPYContext *c, size_t argc, SPYValue *const *argv, SPYValue *keywords, void *data) {
    (void)data;
    if (keywords && keywords->as.map.len) return spy_error(c, "TypeError", "input() takes no keyword arguments");
    if (argc > 1) return errorf(c, "TypeError", "input expected at most 1 argument, got %zu", argc);
    if (c->policy && policy_event(c, "input", argc, argv)) return NULL;
    if (output_flush(c, 0)) return NULL;
    if (argc) {
        SPYValue *text = stringify(c, argv[0], 0);
        int status = text ? print_text(c, NULL, text) : -1;
        spy_release(text);
        if (status || c->error_type[0]) return NULL;
        if (output_flush(c, 0)) return NULL;
    }
    SPYValue *line = c->read_line ? c->read_line(c, c->read_data) : NULL;
    if (!line) return c->error_type[0] ? NULL : spy_error(c, "EOFError", "EOF when reading a line");
    if (line->type != SPY_STRING) {
        errorf(c, "TypeError", "input reader returned %s, not str", type_name(line));
        spy_release(line); return NULL;
    }
    size_t len = line->as.string.len;
    if (len && line->as.string.data[len - 1] == '\n') len--;
    if (len && line->as.string.data[len - 1] == '\r') len--;
    if (len == line->as.string.len) return line;
    SPYValue *result = spy_string(c, line->as.string.data, len);
    spy_release(line);
    return result;
}
static SPYValue *open_builtin(SPYContext *c, size_t argc, SPYValue *const *argv, SPYValue *keywords, void *data) {
    (void)data;
    /* Its arguments are checked as a builtin's (parse_arguments). */
    static const char *const names[] = {"file", "mode", "buffering", "encoding", "errors", "newline", "closefd", "opener"};
    SPYValue *args[8];
    if (parse_arguments(c, "open", argc, argv, keywords, names, 8, 1, 0, args)) return NULL;
    /* A step's open() with keywords calls its intrinsic on its machine,
     * loading the intrinsics there first, as builtin_call's does. */
    Machine *m = step_machine(c);
    SPYValue *ctx = m ? open_context(c, argc, argv, keywords) : NULL;
    if (ctx) return intrinsics_k(c, m, open_loaded, ctx);
    if (c->error_type[0]) return NULL;
    SPYValue *fn = intrinsic(c, "open");
    return fn ? call_keywords(c, fn, argc, argv, keywords) : NULL;
}
#if SPY_FILES
/* Raise the OSError subclass for errno code, as PyErr_SetFromErrnoWithFilenameObject. */
static SPYValue *file_error(SPYContext *c, int code, SPYValue *filename) {
    const char *text = strerror(code);
    SPYValue *args[] = {spy_int(c, code), spy_string(c, text, strlen(text)), filename};
    SPYValue *error = args[0] && args[1] ? exception_create(c, c->exceptions[X_OSERROR], filename ? 3 : 2, args) : NULL;
    if (error) raise_value(c, error);
    spy_release(error); spy_release(args[0]); spy_release(args[1]);
    return NULL;
}
/* Lexically normalize an absolute path in place: no empty, '.', or '..' components. */
static void normalize_path(char *path) {
    char *out = path, *in = path;
    while (*in) {
        while (*in == '/') in++;
        const char *start = in;
        while (*in && *in != '/') in++;
        size_t len = (size_t)(in - start);
        if (!len || (len == 1 && start[0] == '.')) continue;
        if (len == 2 && start[0] == '.' && start[1] == '.') {
            while (out > path && *--out != '/') {}
            continue;
        }
        *out++ = '/';
        memmove(out, start, len);
        out += len;
    }
    if (out == path) *out++ = '/';
    *out = 0;
}
/* Whether path is root or lies under it, component-wise. */
static int path_within(const char *path, const char *root) {
    size_t len = strlen(root);
    if (len == 1) return 1;
    return !strncmp(path, root, len) && (path[len] == 0 || path[len] == '/');
}
/* The host path of a guest path inside the mount that holds it, with the
 * final component unresolved only when it does not exist yet; NULL with errno. */
static char *mount_resolve(SPYContext *c, const char *path, int writing) {
    if (!c->mounts_len) { errno = EACCES; return NULL; }
    size_t size = strlen(path) + strlen(c->mounts[0].path) + 2;
    char *guest = malloc(size);
    if (!guest) { errno = ENOMEM; return NULL; }
    if (path[0] == '/') memcpy(guest, path, strlen(path) + 1);
    else snprintf(guest, size, "%s/%s", c->mounts[0].path, path);
    normalize_path(guest);
    struct Mount *mount = NULL;
    for (size_t i = 0; i < c->mounts_len; i++)
        if (path_within(guest, c->mounts[i].path) && (!mount || strlen(c->mounts[i].path) > strlen(mount->path))) mount = &c->mounts[i];
    if (!mount) { free(guest); errno = EACCES; return NULL; }
    if (writing && (mount->flags & SPY_MOUNT_READ_ONLY)) { free(guest); errno = EROFS; return NULL; }
    const char *rest = guest + (strlen(mount->path) == 1 ? 0 : strlen(mount->path));
    size = strlen(mount->host) + strlen(rest) + 1;
    char *host = malloc(size);
    if (!host) { free(guest); errno = ENOMEM; return NULL; }
    snprintf(host, size, "%s%s", strcmp(mount->host, "/") || !*rest ? mount->host : "", rest);
    free(guest);
    char *real = realpath(host, NULL);
    if (!real && errno == ENOENT) {
        char *slash = strrchr(host, '/');
        *slash = 0;
        char *parent = realpath(*host ? host : "/", NULL);
        if (parent) {
            size = strlen(parent) + strlen(slash + 1) + 2;
            if ((real = malloc(size))) snprintf(real, size, "%s/%s", strcmp(parent, "/") ? parent : "", slash + 1);
            else errno = ENOMEM;
            free(parent);
        }
    }
    free(host);
    if (real && !path_within(real, mount->host)) { free(real); errno = EACCES; return NULL; }
    return real;
}
static ptrdiff_t file_index(SPYContext *c, SPYValue *v, int *fd) {
    int64_t n;
    if (index_value(c, v, &n)) return -1;
    for (size_t i = 0; i < c->files_len; i++)
        if (c->files[i] == n) { *fd = (int)n; return (ptrdiff_t)i; }
    file_error(c, EBADF, NULL);
    return -1;
}
#endif
enum { FILE_OPEN, FILE_READ, FILE_WRITE, FILE_SEEK, FILE_TRUNCATE, FILE_CLOSE };
static SPYValue *file_native(SPYContext *c, size_t argc, SPYValue *const *argv, void *data) {
    static const char *const names[] = {"_file_open", "_file_read", "_file_write", "_file_seek", "_file_truncate", "_file_close"};
    static const size_t counts[] = {2, 2, 2, 3, 2, 1};
    int id = (int)(intptr_t)data;
    if (argc != counts[id]) return errorf(c, "TypeError", "%s() takes %zu arguments (%zu given)", names[id], counts[id], argc);
#if SPY_FILES
    if (id == FILE_OPEN) {
        SPYValue *path = builtin_value(c, argv[0], SPY_STRING), *mode = builtin_value(c, argv[1], SPY_STRING);
        if (!path) path = builtin_value(c, argv[0], SPY_BYTES);
        if (!path || !mode) return spy_error(c, "TypeError", "_file_open() needs a path and a mode string");
        if (strlen(path->as.string.data) != path->as.string.len) return spy_error(c, "ValueError", "embedded null byte");
        const char *m = mode->as.string.data;
        int plus = strchr(m, '+') != NULL, flags = plus ? O_RDWR : m[0] == 'r' ? O_RDONLY : O_WRONLY;
        if (m[0] == 'w') flags |= O_CREAT | O_TRUNC;
        else if (m[0] == 'a') flags |= O_CREAT | O_APPEND;
        else if (m[0] == 'x') flags |= O_CREAT | O_EXCL;
        else if (m[0] != 'r') return errorf(c, "ValueError", "invalid mode: '%s'", m);
        if (c->policy && policy_event(c, "open", 2, (SPYValue *const[]){argv[0], mode})) return NULL;
        if (c->files_len == c->files_cap) {
            size_t cap = c->files_cap ? c->files_cap * 2 : 8;
            int *files = mem_realloc(c, c->files, cap * sizeof(*files));
            if (!files) return spy_error(c, "MemoryError", "out of memory");
            c->files = files; c->files_cap = cap;
        }
        char *real = mount_resolve(c, path->as.string.data, plus || m[0] != 'r');
        if (!real) return file_error(c, errno, argv[0]);
        int fd = open(real, flags | O_CLOEXEC | O_NOFOLLOW, 0666), code = errno;
        free(real);
        if (fd < 0) return file_error(c, code, argv[0]);
        struct stat st;
        if (fstat(fd, &st) || S_ISDIR(st.st_mode)) {
            code = S_ISDIR(st.st_mode) ? EISDIR : errno;
            close(fd);
            return file_error(c, code, argv[0]);
        }
        c->files[c->files_len++] = fd;
        return spy_int(c, fd);
    }
    int fd;
    ptrdiff_t at = file_index(c, argv[0], &fd);
    if (at < 0) return NULL;
    if (id == FILE_CLOSE) {
        c->files[at] = c->files[--c->files_len];
        return close(fd) ? file_error(c, errno, NULL) : spy_none(c);
    }
    if (id == FILE_WRITE) {
        SPYValue *bytes = builtin_value(c, argv[1], SPY_BYTES);
        if (!bytes) bytes = builtin_value(c, argv[1], SPY_BYTEARRAY);
        if (!bytes) return errorf(c, "TypeError", "a bytes-like object is required, not '%s'", type_name(argv[1]));
        size_t done = 0;
        while (done < bytes->as.string.len) {
            ssize_t n = write(fd, bytes->as.string.data + done, bytes->as.string.len - done);
            if (n < 0 && errno == EINTR) continue;
            if (n < 0) return file_error(c, errno, NULL);
            done += (size_t)n;
        }
        return spy_int(c, (int64_t)done);
    }
    int64_t n, whence = 0;
    if (index_value(c, argv[1], &n) || (id == FILE_SEEK && index_value(c, argv[2], &whence))) return NULL;
    if (id == FILE_SEEK) {
        if (whence < 0 || whence > 2) return errorf(c, "ValueError", "invalid whence (%" PRId64 ", should be 0, 1 or 2)", whence);
        off_t pos = lseek(fd, (off_t)n, whence == 0 ? SEEK_SET : whence == 1 ? SEEK_CUR : SEEK_END);
        return pos < 0 ? file_error(c, errno, NULL) : spy_int(c, (int64_t)pos);
    }
    if (id == FILE_TRUNCATE) return ftruncate(fd, (off_t)n) ? file_error(c, errno, NULL) : spy_int(c, n);
    /* FILE_READ: n bytes in one read, or everything to the end when negative. */
    size_t cap = n >= 0 ? (size_t)n : 8192, len = 0;
    char *buffer = mem_malloc(c, cap);
    if (!buffer) return spy_error(c, "MemoryError", "out of memory");
    for (;;) {
        if (len == cap) {
            char *grown = mem_realloc(c, buffer, cap * 2);
            if (!grown) { mem_free(buffer); return spy_error(c, "MemoryError", "out of memory"); }
            buffer = grown; cap *= 2;
        }
        ssize_t got = read(fd, buffer + len, cap - len);
        if (got < 0 && errno == EINTR) continue;
        if (got < 0) { int code = errno; mem_free(buffer); return file_error(c, code, NULL); }
        len += (size_t)got;
        if (n >= 0 || !got) break;
    }
    SPYValue *result = spy_bytes(c, buffer, len);
    mem_free(buffer);
    return result;
#else
    (void)argv;
    return spy_error(c, "OSError", "this build has no file system support");
#endif
}
static int file_natives(SPYContext *c, SPYValue *module) {
    static const char *const names[] = {"_file_open", "_file_read", "_file_write", "_file_seek", "_file_truncate", "_file_close"};
    for (size_t i = 0; i < sizeof(names) / sizeof(*names); i++)
        if (define_native(c, module, names[i], file_native, (void *)(intptr_t)i)) return -1;
    return 0;
}
int spy_mount(SPYContext *c, const char *directory, const char *path, int flags) {
#if SPY_FILES
    struct stat st;
    char *host = realpath(directory, NULL);
    if (!host || stat(host, &st) || !S_ISDIR(st.st_mode)) {
        errorf(c, "OSError", "cannot mount '%s': %s", directory, strerror(host ? ENOTDIR : errno));
        free(host); return -1;
    }
    if (path && path[0] != '/') { free(host); spy_error(c, "ValueError", "a mount path must be absolute"); return -1; }
    char *real = host;
    host = copy_text(c, real, strlen(real));
    free(real);
    char *guest = host ? copy_text(c, path ? path : host, strlen(path ? path : host)) : NULL;
    struct Mount *grown = guest ? mem_realloc(c, c->mounts, (c->mounts_len + 1) * sizeof(*grown)) : NULL;
    if (!grown) { mem_free(host); mem_free(guest); if (!c->error_type[0]) spy_error(c, "MemoryError", "out of memory"); return -1; }
    normalize_path(guest);
    c->mounts = grown;
    c->mounts[c->mounts_len++] = (struct Mount){host, guest, flags};
    return 0;
#else
    (void)directory; (void)path; (void)flags;
    spy_error(c, "OSError", "this build has no file system support");
    return -1;
#endif
}
int spy_new_module(SPYContext *c, const char *name, SPYModuleInit init) {
    size_t i = host_module(c, name);
    if (i == c->host_modules_len) {
        struct HostModule *grown = mem_realloc(c, c->host_modules, (i + 1) * sizeof(*grown));
        if (!grown) { spy_error(c, "MemoryError", "allocation failed"); return -1; }
        c->host_modules = grown;
        if (!(c->host_modules[i].name = copy_text(c, name, strlen(name)))) return -1;
        c->host_modules_len++;
    }
    c->host_modules[i].init = init;
    return 0;
}
int spy_exec_module(SPYContext *c, SPYValue *module, const char *source, const char *filename) {
    if (!same_context(c, module)) return -1;
    if (module->type != SPY_MODULE) { spy_error(c, "TypeError", "spy_exec_module() requires a module"); return -1; }
    enter(c);
    SPYValue *unit = parse(c, source, strlen(source), filename ? filename : "<string>");
    Frame frame = {module, unit, 0};
    Result result = unit ? execute_module(c, &frame) : (Result){FLOW_ERROR, NULL};
    spy_release(result.value); spy_release(unit);
    leave(c, NULL);
    return result.flow == FLOW_ERROR ? -1 : 0;
}
const char *spy_version(void) { return SPY_VERSION; }
void spy_set_opaque(SPYContext *c, void *opaque) { c->opaque = opaque; }
void *spy_get_opaque(const SPYContext *c) { return c->opaque; }
